g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(g),len(g[0]); seen=set()
for r in range(R):
 for c in range(C):
  if g[r][c]!=0 or (r,c) in seen:continue
  q=[(r,c)];seen.add((r,c)); comp=[]
  for x,y in q:
   comp.append((x,y))
   for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
  print(len(comp), min(x for x,y in comp),max(x for x,y in comp),min(y for x,y in comp),max(y for x,y in comp), 'edge', any(x in (0,R-1) or y in (0,C-1) for x,y in comp),comp)
